from __future__ import annotations

import json
import urllib.parse
import urllib.request


def gh_search(query: str, per_page: int = 5) -> list[dict[str, str]]:
    params = {"q": query, "sort": "stars", "order": "desc", "per_page": str(per_page)}
    url = "https://api.github.com/search/repositories?" + urllib.parse.urlencode(params)
    req = urllib.request.Request(
        url,
        headers={
            "User-Agent": "me-sb/figma-rag-bench",
            "Accept": "application/vnd.github+json",
        },
    )
    with urllib.request.urlopen(req, timeout=30) as resp:
        data = json.loads(resp.read().decode("utf-8"))
    items = data.get("items") or []
    out: list[dict[str, str]] = []
    for it in items:
        out.append(
            {
                "full_name": it.get("full_name") or "",
                "html_url": it.get("html_url") or "",
                "description": (it.get("description") or "").strip(),
                "stargazers": str(it.get("stargazers_count") or ""),
            }
        )
    return out


queries = [
    ("Design tokens", "design tokens figma"),
    ("Figma tokens export", "figma tokens studio"),
    ("Figma API", "figma api client"),
]

print("# GitHub repo samples (stars desc)\n")
for label, q in queries:
    try:
        results = gh_search(q, per_page=5)
    except Exception as e:
        print(f"## {label}\n(failed: {type(e).__name__}: {e})\n")
        continue
    print(f"## {label}")
    for r in results:
        print(f"- {r['full_name']} ⭐ {r['stargazers']}\n  {r['html_url']}\n  {r['description']}")
    print("")
